-- Staff collaboration, meetings, board governance and notification center.
create table if not exists public.company_chat_messages(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.company_profiles(id) on delete cascade,sender_user_id uuid not null references auth.users(id) on delete cascade,body text not null check(length(trim(body)) between 1 and 8000),message_type text not null default 'message' check(message_type in ('message','meeting','task','announcement')),created_at timestamptz not null default now());
create table if not exists public.company_chat_reactions(id uuid primary key default gen_random_uuid(),message_id uuid not null references public.company_chat_messages(id) on delete cascade,company_id uuid not null references public.company_profiles(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,reaction text not null check(reaction in ('👍','❤️','😂','🎉','🙏','👀')),created_at timestamptz not null default now(),unique(message_id,user_id,reaction));
create table if not exists public.company_chat_tasks(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.company_profiles(id) on delete cascade,title text not null check(length(trim(title)) between 1 and 180),description text not null default '',assigned_to uuid references auth.users(id) on delete set null,created_by uuid not null references auth.users(id) on delete restrict,due_at timestamptz,status text not null default 'todo' check(status in ('todo','in_progress','done','cancelled')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.company_meetings(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.company_profiles(id) on delete cascade,title text not null,meeting_url text not null check(meeting_url ~* '^https?://'),provider text not null default 'other' check(provider in ('google_meet','zoom','teams','other')),starts_at timestamptz not null,description text not null default '',created_by uuid not null references auth.users(id) on delete restrict,audience text not null default 'staff' check(audience in ('staff','board')),created_at timestamptz not null default now());
create table if not exists public.company_board_members(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.company_profiles(id) on delete cascade,full_name text not null,email text not null,position_title text not null,phone text not null default '',user_id uuid references auth.users(id) on delete set null,added_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),unique(company_id,email));
create table if not exists public.company_board_records(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.company_profiles(id) on delete cascade,record_type text not null check(record_type in ('meeting','decision','idea','outcome')),title text not null,body text not null default '',starts_at timestamptz,meeting_url text,visibility text not null default 'board_only' check(visibility in ('board_only','published')),created_by uuid not null references auth.users(id) on delete restrict,published_at timestamptz,created_at timestamptz not null default now(),check(meeting_url is null or meeting_url ~* '^https?://'));
create table if not exists public.company_workspace_notifications(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.company_profiles(id) on delete cascade,title text not null,body text not null default '',notification_type text not null default 'general',audience text not null default 'staff' check(audience in ('staff','board')),related_id uuid,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now());
create table if not exists public.company_notification_reads(notification_id uuid not null references public.company_workspace_notifications(id) on delete cascade,company_id uuid not null references public.company_profiles(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,read_at timestamptz not null default now(),primary key(notification_id,user_id));
create index if not exists company_chat_messages_company_created_idx on public.company_chat_messages(company_id,created_at desc);
create index if not exists company_chat_tasks_company_status_idx on public.company_chat_tasks(company_id,status,due_at);
create index if not exists company_meetings_company_start_idx on public.company_meetings(company_id,starts_at);
create index if not exists company_board_records_company_created_idx on public.company_board_records(company_id,created_at desc);
create index if not exists company_workspace_notifications_company_created_idx on public.company_workspace_notifications(company_id,created_at desc);
alter table public.company_chat_messages enable row level security;alter table public.company_chat_reactions enable row level security;alter table public.company_chat_tasks enable row level security;alter table public.company_meetings enable row level security;alter table public.company_board_members enable row level security;alter table public.company_board_records enable row level security;alter table public.company_workspace_notifications enable row level security;alter table public.company_notification_reads enable row level security;
drop policy if exists chat_messages_member_read on public.company_chat_messages;create policy chat_messages_member_read on public.company_chat_messages for select to authenticated using(exists(select 1 from public.company_members m where m.company_id=company_chat_messages.company_id and m.user_id=(select auth.uid()) and m.status='active'));
drop policy if exists chat_messages_member_insert on public.company_chat_messages;create policy chat_messages_member_insert on public.company_chat_messages for insert to authenticated with check(sender_user_id=(select auth.uid()) and exists(select 1 from public.company_members m where m.company_id=company_chat_messages.company_id and m.user_id=(select auth.uid()) and m.status='active'));
drop policy if exists chat_reactions_member_all on public.company_chat_reactions;create policy chat_reactions_member_all on public.company_chat_reactions for all to authenticated using(exists(select 1 from public.company_members m where m.company_id=company_chat_reactions.company_id and m.user_id=(select auth.uid()) and m.status='active')) with check(user_id=(select auth.uid()) and exists(select 1 from public.company_members m where m.company_id=company_chat_reactions.company_id and m.user_id=(select auth.uid()) and m.status='active'));
drop policy if exists chat_tasks_member_read on public.company_chat_tasks;create policy chat_tasks_member_read on public.company_chat_tasks for select to authenticated using(exists(select 1 from public.company_members m where m.company_id=company_chat_tasks.company_id and m.user_id=(select auth.uid()) and m.status='active'));
drop policy if exists chat_tasks_manager_create on public.company_chat_tasks;create policy chat_tasks_manager_create on public.company_chat_tasks for insert to authenticated with check(created_by=(select auth.uid()) and exists(select 1 from public.company_members m where m.company_id=company_chat_tasks.company_id and m.user_id=(select auth.uid()) and m.status='active' and lower(m.role) in ('owner','admin','manager')));
drop policy if exists chat_tasks_authorized_update on public.company_chat_tasks;create policy chat_tasks_authorized_update on public.company_chat_tasks for update to authenticated using(exists(select 1 from public.company_members m where m.company_id=company_chat_tasks.company_id and m.user_id=(select auth.uid()) and m.status='active' and (lower(m.role) in ('owner','admin','manager') or company_chat_tasks.assigned_to=(select auth.uid())))) with check(exists(select 1 from public.company_members m where m.company_id=company_chat_tasks.company_id and m.user_id=(select auth.uid()) and m.status='active'));
drop policy if exists meetings_member_read on public.company_meetings;create policy meetings_member_read on public.company_meetings for select to authenticated using(exists(select 1 from public.company_members m where m.company_id=company_meetings.company_id and m.user_id=(select auth.uid()) and m.status='active') and (audience='staff' or exists(select 1 from public.company_members m where m.company_id=company_meetings.company_id and m.user_id=(select auth.uid()) and lower(m.role) in ('owner','admin')) or exists(select 1 from public.company_board_members b where b.company_id=company_meetings.company_id and b.user_id=(select auth.uid())));
drop policy if exists meetings_authorized_create on public.company_meetings;create policy meetings_authorized_create on public.company_meetings for insert to authenticated with check(created_by=(select auth.uid()) and exists(select 1 from public.company_members m where m.company_id=company_meetings.company_id and m.user_id=(select auth.uid()) and m.status='active' and lower(m.role) in ('owner','admin','manager')));
drop policy if exists board_members_owner_manage on public.company_board_members;create policy board_members_owner_manage on public.company_board_members for all to authenticated using(exists(select 1 from public.company_members m where m.company_id=company_board_members.company_id and m.user_id=(select auth.uid()) and m.status='active' and lower(m.role) in ('owner','admin'))) with check(added_by=(select auth.uid()) and exists(select 1 from public.company_members m where m.company_id=company_board_members.company_id and m.user_id=(select auth.uid()) and m.status='active' and lower(m.role) in ('owner','admin')));
drop policy if exists board_member_self_read on public.company_board_members;create policy board_member_self_read on public.company_board_members for select to authenticated using(user_id=(select auth.uid()) and exists(select 1 from public.company_members m where m.company_id=company_board_members.company_id and m.user_id=(select auth.uid()) and m.status='active'));
drop policy if exists board_records_confidential_access on public.company_board_records;create policy board_records_confidential_access on public.company_board_records for select to authenticated using(exists(select 1 from public.company_members m where m.company_id=company_board_records.company_id and m.user_id=(select auth.uid()) and m.status='active' and lower(m.role) in ('owner','admin')) or exists(select 1 from public.company_board_members b where b.company_id=company_board_records.company_id and b.user_id=(select auth.uid())) or (visibility='published' and exists(select 1 from public.company_members m where m.company_id=company_board_records.company_id and m.user_id=(select auth.uid()) and m.status='active')));
drop policy if exists board_records_board_create on public.company_board_records;create policy board_records_board_create on public.company_board_records for insert to authenticated with check(created_by=(select auth.uid()) and (exists(select 1 from public.company_members m where m.company_id=company_board_records.company_id and m.user_id=(select auth.uid()) and m.status='active' and lower(m.role) in ('owner','admin')) or exists(select 1 from public.company_board_members b where b.company_id=company_board_records.company_id and b.user_id=(select auth.uid()))));
drop policy if exists board_records_owner_update on public.company_board_records;create policy board_records_owner_update on public.company_board_records for update to authenticated using(exists(select 1 from public.company_members m where m.company_id=company_board_records.company_id and m.user_id=(select auth.uid()) and m.status='active' and lower(m.role) in ('owner','admin'))) with check(exists(select 1 from public.company_members m where m.company_id=company_board_records.company_id and m.user_id=(select auth.uid()) and m.status='active' and lower(m.role) in ('owner','admin')));
drop policy if exists notifications_member_read on public.company_workspace_notifications;create policy notifications_member_read on public.company_workspace_notifications for select to authenticated using(exists(select 1 from public.company_members m where m.company_id=company_workspace_notifications.company_id and m.user_id=(select auth.uid()) and m.status='active') and (audience='staff' or exists(select 1 from public.company_members m where m.company_id=company_workspace_notifications.company_id and m.user_id=(select auth.uid()) and lower(m.role) in ('owner','admin')) or exists(select 1 from public.company_board_members b where b.company_id=company_workspace_notifications.company_id and b.user_id=(select auth.uid())));
drop policy if exists notifications_member_create on public.company_workspace_notifications;create policy notifications_member_create on public.company_workspace_notifications for insert to authenticated with check(created_by=(select auth.uid()) and exists(select 1 from public.company_members m where m.company_id=company_workspace_notifications.company_id and m.user_id=(select auth.uid()) and m.status='active'));
drop policy if exists notification_reads_self on public.company_notification_reads;create policy notification_reads_self on public.company_notification_reads for all to authenticated using(user_id=(select auth.uid()) and exists(select 1 from public.company_members m where m.company_id=company_notification_reads.company_id and m.user_id=(select auth.uid()) and m.status='active')) with check(user_id=(select auth.uid()) and exists(select 1 from public.company_members m where m.company_id=company_notification_reads.company_id and m.user_id=(select auth.uid()) and m.status='active'));
grant select,insert on public.company_chat_messages to authenticated;grant select,insert,delete on public.company_chat_reactions to authenticated;grant select,insert,update on public.company_chat_tasks to authenticated;grant select,insert on public.company_meetings to authenticated;grant select,insert,update,delete on public.company_board_members to authenticated;grant select,insert,update on public.company_board_records to authenticated;grant select,insert on public.company_workspace_notifications to authenticated;grant select,insert,update on public.company_notification_reads to authenticated;